#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
"""Export a FISH session to Chrome Trace Event JSON — open with ui.perfetto.dev ("Open trace file", works offline
once loaded; also `tracy-import-chrome` for Tracy). The SVG gantt chokes above ~40k spans; Perfetto renders millions.

  python3 export_perfetto.py <session_id> [-o out.json] [--all-window] [--infra] [--pairs pairs.json] [--from-s A --to-s B]

Tracks:   one process group per ROS process (executor vertex), one track per thread → callback slices
          (name = entity, args: node, symbol, and — with ksched_inst — on-CPU / runnable / preempted / sleeping /
          GPU-wait / lock-wait of that instance in ms);
          process "GPU" → one track per CUDA stream: kernels and memcpys (CUPTI);
          flow arrows publish → consumer start for every paired trigger instance (--pairs from extract_fish_tasks.py).
Default window: the steady-state window (fish_window); --all-window = whole data phase. Infra callbacks (/clock,
/parameter_events, parameter services: ~80 % of all slices) are dropped unless --infra. Times in µs from window start."""
import argparse, json, re, sys, os
import psycopg2
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from topic_class import topic_class
from fish_window import steady_window
DSN = 'host=localhost port=5432 dbname=fish user=fish password=fish'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('session'); ap.add_argument('--scope', default='__main__'); ap.add_argument('-o', '--out', default=None)
    ap.add_argument('--all-window', action='store_true'); ap.add_argument('--infra', action='store_true')
    ap.add_argument('--pairs', default=None); ap.add_argument('--from-s', type=float, default=None); ap.add_argument('--to-s', type=float, default=None)
    a = ap.parse_args()
    sid = a.session; out = a.out or f'{sid}.perfetto.json'
    conn = psycopg2.connect(DSN); cur = conn.cursor()
    W = steady_window(cur, sid, a.scope, warmup_s=0 if a.all_window else None)
    t0w, t1w = W['t_ss'], W['t_end']
    if a.from_s is not None: t0w = W['t_ss'] + int(a.from_s * 1e9)
    if a.to_s is not None: t1w = W['t_ss'] + int(a.to_s * 1e9)
    us = lambda t: (t - t0w) / 1000.0
    ev = []
    cur.execute("SELECT pid, label, attrs FROM graph_nodes WHERE session_id=%s AND scope=%s AND type='EX'", (sid, a.scope))
    for pid, label, attrs in cur.fetchall():
        ev.append(dict(ph='M', name='process_name', pid=pid, tid=0, args=dict(name=re.sub(r' \(PID:\d+\)', '', label or str(pid)) + f' [{pid}]')))
        for t in (attrs or {}).get('threads') or []:
            ev.append(dict(ph='M', name='thread_name', pid=pid, tid=t.get('tid'), args=dict(name=f"{t.get('comm')} {t.get('tid')}")))
    K = {}
    try:
        cur.execute("SELECT pid, vtid, t0_ns, on_ns, pre_ns, run_ns, slp_ns, gpu_ns, lock_ns FROM ksched_inst WHERE session_id=%s AND scope=%s AND t0_ns BETWEEN %s AND %s",
                    (sid, a.scope, t0w, t1w))
        for r in cur: K[(r[0], r[1], r[2])] = r[3:]
    except psycopg2.Error:
        conn.rollback()
    cur.execute("SELECT pid, vtid, t0_ns, t1_ns, node, entity, etype, symbol FROM gantt_spans WHERE session_id=%s AND scope=%s AND t0_ns BETWEEN %s AND %s ORDER BY t0_ns",
                (sid, a.scope, t0w, t1w))
    n = 0
    for pid, vtid, t0, t1, node, ent, etype, sym in cur:
        e = ent or ''
        if not a.infra and ((e.startswith('sub:') and topic_class(e[4:]) == 'infra') or 'parameter' in e):
            continue
        args = dict(node=node, symbol=(sym or '')[:160])
        k = K.get((pid, vtid, t0))
        if k:
            args.update(on_cpu_ms=k[0] / 1e6, preempted_ms=k[1] / 1e6, runnable_ms=k[2] / 1e6, sleeping_ms=k[3] / 1e6, gpu_wait_ms=k[4] / 1e6, lock_wait_ms=k[5] / 1e6)
        ev.append(dict(ph='X', name=e or (sym or '?')[:60], cat=etype or 'cb', pid=pid, tid=vtid, ts=us(t0), dur=max(0.001, (t1 - t0) / 1000.0), args=args)); n += 1
    # GPU tracks
    GP = 9_000_000
    ev.append(dict(ph='M', name='process_name', pid=GP, tid=0, args=dict(name='GPU (CUPTI: kernels, memcpy) per CUDA stream')))
    g = 0
    cur.execute("SELECT ts_ns, duration_ns, kernel_short_name, stream_id, grid_x*grid_y*grid_z, block_x*block_y*block_z, source FROM gpu_kernels WHERE session_id=%s AND ts_ns BETWEEN %s AND %s", (sid, t0w, t1w))
    for ts, d, name, stream, blocks, tpb, src in cur:
        ev.append(dict(ph='X', name=name or 'kernel', cat='sm', pid=GP, tid=int(stream or 0), ts=us(ts), dur=max(0.001, (d or 0) / 1000.0), args=dict(blocks=blocks, threads_per_block=tpb, source=src))); g += 1
    KIND = {1: 'HtoD', 2: 'DtoH', 8: 'DtoD', 10: 'PtoP'}
    cur.execute("SELECT ts_ns, duration_ns, bytes, copy_kind, stream_id FROM gpu_memcpy WHERE session_id=%s AND ts_ns BETWEEN %s AND %s", (sid, t0w, t1w))
    for ts, d, b, kind, stream in cur:
        ev.append(dict(ph='X', name=f"memcpy {KIND.get(kind, kind)}", cat='ce', pid=GP, tid=int(stream or 0), ts=us(ts), dur=max(0.001, (d or 0) / 1000.0), args=dict(bytes=b))); g += 1
    # flows
    nf = 0
    if a.pairs and os.path.exists(a.pairs):
        P = json.load(open(a.pairs)); topics = P['topics']
        for i, (up, ut, pt, vp, vt, vs, ti, kind) in enumerate(P['flows']):
            if not (t0w <= pt <= t1w and t0w <= vs <= t1w):
                continue
            nm = topics[ti]
            ev.append(dict(ph='s', id=i, name=nm, cat=kind, pid=up, tid=ut, ts=us(pt)))
            ev.append(dict(ph='f', bp='e', id=i, name=nm, cat=kind, pid=vp, tid=vt, ts=us(vs) + 0.001)); nf += 1
    json.dump(dict(traceEvents=ev, displayTimeUnit='ms', metadata=dict(session=sid, window_ns=[t0w, t1w])), open(out, 'w'))
    print(f"{out}: {n} callback slices, {g} GPU slices, {nf} flows, {os.path.getsize(out) / 1e6:.1f} MB — open at https://ui.perfetto.dev")


if __name__ == '__main__':
    main()
